function hero_summary($item){$text=trim((string)($item['editorial']['description']??$item['description']??$item['plot']??''));return $text!==''?$text:'Explorează povestea, distribuția și detaliile acestui '.(title_type($item)==='tv'?'serial':'film').'.';}
function hero_meta_text($item){return implode(' · ',array_filter([type_label(title_type($item)),(string)($item['year']??''),!empty($item['runtime'])?duration_label($item['runtime']):'',implode(' / ',array_map('genre_label',array_slice(public_genres($item['genres']??[]),0,2))),!empty($item['rating'])?'IMDb ★ '.number_format((float)$item['rating'],1,',',''):'']));}
?>
<section class="cinematic-intro" aria-labelledby="introTitle"><div class="hero-backdrops" aria-hidden="true"><?php foreach($heroItems as $i=>$item):remember_title_preview($item);?><img class="hero-backdrop" src="<?=e(item_background_url($item))?>" alt="" referrerpolicy="no-referrer" <?=$i===0?'fetchpriority="high" loading="eager"':'loading="lazy" hidden'?> decoding="async" data-fallback="<?=e(item_poster_url($item))?>" data-feature-title="<?=e(title_name($item))?>" data-feature-url="<?=e(title_path($item))?>" data-feature-meta="<?=e(hero_meta_text($item))?>" data-feature-description="<?=e(hero_summary($item))?>" data-feature-type="<?=e(title_type($item))?>" data-feature-id="<?=e($item['imdb_id'])?>"><?php endforeach;?></div><div class="hero-shade"></div><div class="wrap cinematic-inner"><div class="hero-copy"><span class="section-kicker">În prim-plan</span><h1 id="introTitle"><?=e($heroFirst?title_name($heroFirst):'Următoarea poveste începe aici.')?></h1><p class="hero-meta" id="heroMeta"><?=e($heroFirst?hero_meta_text($heroFirst):'Filme și seriale pentru fiecare seară')?></p><p class="hero-description" id="heroDescription"><?=e($heroFirst?hero_summary($heroFirst):'Descoperă catalogul și găsește ceva pe gustul tău.')?></p><div class="hero-actions"><a class="primary-btn" id="featuredMovieAction" href="<?=e($heroFirst?title_path($heroFirst):'/catalog/')?>"><?=icon('play')?> <span>Vezi detalii</span></a><button class="ghost-btn js-trailer hero-trailer" type="button" hidden><?=icon('play')?> Trailer</button><a class="text-btn hero-catalog-link" href="/catalog/">Catalog <?=icon('arrow')?></a></div></div><?php if(count($heroItems)>1):?><div class="hero-controls" aria-label="Titluri în prim-plan"><button class="hero-prev icon-btn" aria-label="Titlul precedent">‹</button><span class="hero-position" aria-live="polite">01 / <?=str_pad((string)count($heroItems),2,'0',STR_PAD_LEFT)?></span><button class="hero-next icon-btn" aria-label="Titlul următor">›</button></div><?php endi